scriptData.script:
// Expanded Criticals: choice prompted when this critical is received (generated by tools/crit-tests.mjs).
// Asked of the actor's player when the GM adds it (module setting "Who rolls critical Tests").
const api = game.modules.get("artantares-advanced-criticals")?.api;
if (!api?.rollCritTest) return ui.notifications.error("Expanded Criticals is not active: roll this critical's Test by hand.");
{
  const choice = await api.chooseCritOption(this, { prompt: "That is not survivable. Spend Fate, or, out of Fate Points, a Resilience Point to twist away?", options: [
    { id: "fate", label: "Spend a Fate Point", hint: "You avoid death; the GM decides what happens instead.", disabled: !(Number(this.actor.system.status?.fate?.value ?? 0) > 0) },
    { id: "resilience", label: "Spend a Resilience Point: Prone, Stunned (3) and Bleeding (1)", hint: "Only when out of Fate Points.", disabled: !(Number(this.actor.system.status?.fate?.value ?? 0) <= 0 && Number(this.actor.system.status?.resilience?.value ?? 0) > 0) },
    { id: "die", label: "Accept death" }
  ] });
  if (choice === "fate") {
    await this.actor.update({"system.status.fate.value": Number(this.actor.system.status.fate.value) - 1});
    await api.gmNote(this, "Spent a Fate Point to avoid death. The GM decides what happens instead.");
  }
  else if (choice === "resilience") {
    await this.actor.update({"system.status.resilience.value": Number(this.actor.system.status.resilience.value) - 1});
    await this.actor.addCondition("prone");
    await this.actor.addCondition("stunned", 3);
    await this.actor.addCondition("bleeding", 1);
  }
  else if (choice === "die") {
    await this.actor.addCondition("dead");
  }
}
